import re
import os

artifacts_path = '/home/ubuntu/.agent-ml-research-idea_gen_0514_4/projects/distrib_canary_collapse/artifacts'

# Scan artifact directories to verify completion
artifact_data = {}
for item in os.listdir(artifacts_path):
    full_path = os.path.join(artifacts_path, item)
    if not os.path.isdir(full_path):
        continue

    if not item.startswith('alpha_sweep_a'):
        continue

    # Parse exp_id
    alpha_match = re.search(r'_a(\d{3})', item)
    seed_match = re.search(r'_s(\d+)', item)

    if alpha_match and seed_match and 'fp32' in item:
        alpha = int(alpha_match.group(1)) / 100
        seed = int(seed_match.group(1))

        # Check if results exist
        results_files = []
        for root, dirs, files in os.walk(full_path):
            for f in files:
                if 'results' in f.lower() and f.endswith('.json'):
                    results_files.append(f)

        artifact_data[item] = {
            'alpha': alpha,
            'seed': seed,
            'has_results': len(results_files) > 0,
            'result_files': results_files[:2]
        }

print(f"Artifact directories with fp32 Pythia-410M alpha_sweep: {len(artifact_data)}")
print("\nVerification: Artifact directories by alpha level:")

alpha_from_artifacts = {}
for exp_id, data in sorted(artifact_data.items()):
    alpha = data['alpha']
    seed = data['seed']
    if alpha not in alpha_from_artifacts:
        alpha_from_artifacts[alpha] = set()
    alpha_from_artifacts[alpha].add(seed)
    status = "✓ has results" if data['has_results'] else "? no results"
    print(f"  {exp_id}: {status}")

print("\n\nArtifact-based seed count:")
target_alphas = [0.00, 0.05, 0.10, 0.15, 0.20, 0.25, 0.30, 0.40, 0.45, 0.50, 0.55, 0.60, 0.75, 1.0]
for alpha in target_alphas:
    if alpha in alpha_from_artifacts:
        seeds = sorted(alpha_from_artifacts[alpha])
        print(f"  alpha={alpha:.2f}: {len(seeds)} seed(s) {seeds}")

